/* ═══ СИНГУЛЯР·01 · Квантовая Сансара — прототип: куб → колесо 157 голосов → караоке ═══ */
:root{
  --coal:#000; --edge:#1f1c1a; --skin:#e8e4df; --ash:#8a8580; --mute:#8a8580;
  --ember:#ffab40; --coal2:#c45c26; --dim:rgba(232,228,223,.34);
  --spoke-glow:rgba(255,171,64,.55);
  --fd:"Unbounded","Manrope",system-ui,sans-serif;
  --fb:"Manrope","Golos Text",system-ui,sans-serif;
  --fm:"JetBrains Mono","SF Mono",monospace,sans-serif;
  --sat:env(safe-area-inset-top,0px); --sab:env(safe-area-inset-bottom,0px);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{background:var(--coal);color:var(--skin);font-family:var(--fb);overflow:hidden;
  -webkit-font-smoothing:antialiased;min-height:100dvh}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
.sr-only{position:absolute;width:1px;height:1px;clip:rect(0 0 0 0);overflow:hidden;white-space:nowrap}

/* ── канвасы ── */
#gl,#fx{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
body.no-webgl #gl,body.no-webgl #fx{display:none}
body.no-webgl{background:radial-gradient(120vmax 90vmax at 50% 18%,#1a1208 0%,#000 62%)}
html[data-motion="off"] #gl,html[data-motion="off"] #fx{display:none}

/* ── топбар ── */
.topbar{position:fixed;top:0;left:0;right:0;z-index:70;display:flex;align-items:center;gap:.55rem;
  padding:calc(.6rem + var(--sat)) 1rem .6rem;font-family:var(--fd)}
.brand{font-weight:700;font-size:.92rem;letter-spacing:.06em;text-decoration:none;color:var(--skin);white-space:nowrap}
.brand span{color:var(--ash);font-weight:400}
.brand .ver{color:var(--ember);font-size:.6rem;letter-spacing:.22em;margin-left:.45rem;vertical-align:middle}
.counter{font-family:var(--fm);font-size:.68rem;color:var(--ash);letter-spacing:.08em;white-space:nowrap}
.grow{flex:1}
.tbtn{font-family:var(--fm);font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ash);
  border:1px solid var(--edge);border-radius:999px;padding:.34rem .72rem;transition:.18s;white-space:nowrap}
.tbtn:hover,.tbtn:focus-visible{color:var(--ember);border-color:var(--spoke-glow)}
.tbtn[aria-pressed="true"]{color:var(--ember);border-color:var(--ember)}

/* ── подсказка ── */
.back-hint{position:fixed;top:calc(2.6rem + var(--sat));left:0;right:0;text-align:center;z-index:5;
  font-size:.66rem;color:var(--mute);letter-spacing:.08em}

/* ── сцена: куб + колесо ── */
.stage{position:relative;z-index:6;width:min(94vmin,860px);height:min(94vmin,860px);margin:0 auto;
  display:grid;place-items:center;top:50%;transform:translateY(-47%)}
.cube-wrap{position:relative;z-index:8;width:22%;aspect-ratio:1;cursor:pointer;outline:none;
  transition:opacity .6s,transform .9s cubic-bezier(.6,0,.3,1)}
.cube-wrap:hover .cube{filter:drop-shadow(0 0 22px var(--spoke-glow))}
.cube-wrap.gone{opacity:0;transform:scale(.35) rotate(35deg);pointer-events:none}
.cube{position:absolute;inset:0;transform-style:preserve-3d;animation:cspin 26s linear infinite}
@keyframes cspin{from{transform:rotateX(-24deg) rotateY(0)}to{transform:rotateX(-24deg) rotateY(360deg)}}
.face{position:absolute;inset:6%;border:1.5px solid var(--ember);background:
  linear-gradient(135deg,rgba(255,171,64,.09),rgba(0,0,0,.55));box-shadow:inset 0 0 34px rgba(255,171,64,.13)}
.f-front{transform:translateZ(50%)} .f-back{transform:rotateY(180deg) translateZ(50%)}
.f-right{transform:rotateY(90deg) translateZ(50%)} .f-left{transform:rotateY(-90deg) translateZ(50%)}
.f-top{transform:rotateX(90deg) translateZ(50%)} .f-bottom{transform:rotateX(-90deg) translateZ(50%)}
.hint{position:absolute;bottom:2%;left:0;right:0;text-align:center;font-size:.7rem;color:var(--mute);
  letter-spacing:.14em;text-transform:uppercase;z-index:8;transition:opacity .5s}
.hint.gone{opacity:0}

/* колесо */
.wheel{position:absolute;inset:0;z-index:7;opacity:0;pointer-events:none;transition:opacity 1.1s .25s}
.wheel.on{opacity:1;pointer-events:auto}
.wheel-inner{position:absolute;inset:0}
.wheel-rotator{position:absolute;inset:0;animation:wr 240s linear infinite}
@keyframes wr{to{transform:rotate(360deg)}}
html[data-motion="off"] .wheel-rotator{animation:none}
.wn{position:absolute;width:1.6vmin;height:1.6vmin;min-width:9px;min-height:9px;margin:-.8vmin 0 0 -.8vmin;
  border-radius:50%;border:1px solid rgba(255,171,64,.5);background:rgba(0,0,0,.35);
  animation:wr 240s linear infinite reverse;display:grid;place-items:center;cursor:pointer;transition:border-color .2s}
.wn i{width:.42vmin;height:.42vmin;min-width:3px;min-height:3px;border-radius:50%;background:var(--dim);transition:.2s}
.wn:hover .nm,.wn:focus-visible .nm{opacity:1}
.wn:focus-visible{border-color:var(--ember)}
.wn.heard i{background:var(--ember);box-shadow:0 0 8px var(--spoke-glow)}
.wn .nm{position:absolute;bottom:130%;left:50%;transform:translateX(-50%) rotate(var(--unrot));white-space:nowrap;
  font-size:.62rem;letter-spacing:.06em;color:var(--ember);background:rgba(0,0,0,.82);border:1px solid var(--edge);
  border-radius:6px;padding:.18rem .5rem;opacity:0;pointer-events:none;transition:.15s;z-index:40}
.axis{position:absolute;left:50%;top:50%;width:11%;height:11%;transform:translate(-50%,-50%);border-radius:50%;
  border:1px solid var(--edge);background:radial-gradient(circle,rgba(255,171,64,.16),rgba(0,0,0,.7) 70%);
  display:grid;place-items:center;z-index:9;cursor:pointer;transition:.25s}
.axis:hover{border-color:var(--ember)}
.axis b{font-family:var(--fm);font-size:.6rem;letter-spacing:.18em;color:var(--ember);font-weight:400}

/* призрак куба в центре */
.ghost{position:absolute;left:50%;top:50%;width:5.5%;aspect-ratio:1;transform:translate(-50%,-50%);
  border:1px solid rgba(255,171,64,.35);outline:1px solid rgba(255,171,64,.14);outline-offset:4px;
  animation:brz 7s ease-in-out infinite;z-index:8;pointer-events:none}
@keyframes brz{50%{transform:translate(-50%,-50%) rotate(45deg) scale(.92)}}

/* легенда кругов */
.legend{position:fixed;left:0;right:0;bottom:calc(.9rem + var(--sab));z-index:5;text-align:center;
  font-size:.62rem;color:var(--mute);letter-spacing:.1em;padding:0 1rem;line-height:1.7}
.legend b{color:var(--ember);font-weight:600}

/* ── карточка песни + заглушки ── */
.songs{position:fixed;z-index:20;left:50%;transform:translateX(-50%);bottom:calc(3.4rem + var(--sab));
  display:flex;gap:.6rem;align-items:stretch;max-width:min(96vw,980px);overflow-x:auto;padding:.4rem .6rem;
  scrollbar-width:none;transition:opacity .5s}
.songs.gone{opacity:0;pointer-events:none}
.songs::-webkit-scrollbar{display:none}
.sc{flex:0 0 auto;display:flex;gap:.7rem;align-items:center;border:1px solid var(--edge);border-radius:12px;
  padding:.55rem .85rem;background:rgba(10,8,6,.78);backdrop-filter:blur(6px);min-width:210px;text-align:left;transition:.2s}
.sc img{width:56px;height:31px;object-fit:cover;border-radius:5px;filter:saturate(.9)}
.sc .t{font-size:.74rem;font-weight:600;letter-spacing:.02em}
.sc .m{font-family:var(--fm);font-size:.6rem;color:var(--ash);margin-top:.15rem}
.sc.live{border-color:var(--ember);box-shadow:0 0 22px rgba(255,171,64,.14)}
.sc.live .m{color:var(--ember)}
.sc.soon{opacity:.45;filter:grayscale(.4)}
.sc.soon:hover{opacity:.75}

/* ── панель караоке ── */
.panel{position:fixed;top:0;right:0;bottom:0;z-index:50;width:min(560px,100vw);display:flex;flex-direction:column;
  background:rgba(6,5,4,.92);backdrop-filter:blur(14px);border-left:1px solid var(--edge);
  transform:translateX(102%);transition:transform .45s cubic-bezier(.6,0,.25,1);padding:calc(3.5rem + var(--sat)) 0 calc(.7rem + var(--sab))}
.panel.open{transform:translateX(0)}
.p-head{display:flex;flex-direction:column;gap:.3rem;padding:0 1.1rem .55rem;border-bottom:1px solid var(--edge)}
.p-chip{display:flex;align-items:center;gap:.5rem;font-family:var(--fm);font-size:.62rem;letter-spacing:.1em}
.p-chip .lc{color:#000;background:var(--ember);border-radius:5px;padding:.16rem .5rem;font-weight:700;text-transform:uppercase}
.p-chip .ln{color:var(--ash)}
.p-title{font-family:var(--fd);font-size:1.18rem;font-weight:700;letter-spacing:.01em}
.p-artist{font-size:.68rem;color:var(--ash);letter-spacing:.12em;text-transform:uppercase}
.p-note{font-size:.6rem;color:var(--mute)}

.transport{display:flex;align-items:center;gap:.7rem;padding:.6rem 1.1rem}
.bt{width:2.5rem;height:2.5rem;border-radius:50%;border:1px solid var(--ember);color:var(--ember);
  display:grid;place-items:center;font-size:1rem;transition:.2s;flex:0 0 auto}
.bt:hover{background:rgba(255,171,64,.12);box-shadow:0 0 18px var(--spoke-glow)}
.timecode{font-family:var(--fm);font-size:.66rem;color:var(--ash);white-space:nowrap}
.rail{flex:1;height:22px;display:grid;align-items:center;cursor:pointer}
.rail .tr{position:relative;height:3px;background:var(--edge);border-radius:2px}
.rail .fill{position:absolute;inset:0 auto 0 0;background:var(--ember);border-radius:2px;width:0%}
.rail .head{position:absolute;top:50%;width:11px;height:11px;border-radius:50%;background:var(--ember);
  transform:translate(-50%,-50%);box-shadow:0 0 10px var(--spoke-glow)}

.kwrap{flex:1;position:relative;overflow:hidden;min-height:0}
.kstage{position:absolute;inset:0;overflow-y:auto;scrollbar-width:none;padding:0 1.1rem;
  mask-image:linear-gradient(transparent,#000 16%,#000 84%,transparent);-webkit-mask-image:linear-gradient(transparent,#000 16%,#000 84%,transparent)}
.kstage::-webkit-scrollbar{display:none}
.kstack{display:flex;flex-direction:column;gap:.4rem;padding:38% 0 52%;will-change:transform}
.kl{--wp:0;font-size:clamp(1.02rem,2.6vh,1.3rem);line-height:1.42;color:var(--dim);cursor:pointer;
  border-radius:.5rem;padding:.18rem .45rem;transition:color .3s;min-height:1.5em}
.kl:hover{color:var(--ash)}
.kl.act{color:var(--skin)}
.kl.past{color:rgba(232,228,223,.16)}
.kl.song{font-family:var(--fd)}
.kl.idle{color:var(--coal2);font-style:italic;font-family:var(--fm);font-size:.9em;text-align:center;
  animation:brz2 2.6s ease-in-out infinite}
@keyframes brz2{50%{opacity:.45;transform:scale(.97)}}
.kl .w{background-image:linear-gradient(90deg,var(--ember) var(--wp),transparent var(--wp));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.kl .w:not(.lit){background-image:none;color:inherit;background-clip:border-box;-webkit-background-clip:border-box}
.kl.act .w{color:var(--skin)}
.kl.act .w.lit{background-image:linear-gradient(90deg,var(--ember) var(--wp),var(--skin) var(--wp));
  -webkit-background-clip:text;background-clip:text}
.kstage[dir="rtl"] .kl.act .w.lit{background-image:linear-gradient(270deg,var(--ember) var(--wp),var(--skin) var(--wp))}
.kl.past .w,.kl.song .w{background-image:none;color:inherit;-webkit-background-clip:border-box;background-clip:border-box}
.kstage.scroll{overflow-y:auto}
.sc .ph-ic{width:56px;text-align:center;font-size:1.25rem;color:var(--coal2)}

.p-actions{display:flex;flex-wrap:wrap;gap:.45rem;align-items:center;padding:.55rem 1.1rem;border-top:1px solid var(--edge)}
.ab{font-family:var(--fm);font-size:.64rem;letter-spacing:.08em;border:1px solid var(--edge);border-radius:8px;
  padding:.4rem .6rem;color:var(--ash);transition:.18s;white-space:nowrap}
.ab:hover{color:var(--ember);border-color:var(--spoke-glow)}
.ab[aria-pressed="true"]{color:var(--ember);border-color:var(--ember)}
.spacer{flex:1}
.shift{display:flex;align-items:center;gap:.4rem;font-family:var(--fm);font-size:.6rem;color:var(--mute)}
.shift input{width:86px;accent-color:var(--ember)}
.shift b{color:var(--ash);min-width:3.4ch;text-align:right;font-weight:400}

/* ── сетка языков ── */
.gridview{position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.86);backdrop-filter:blur(10px);
  display:flex;flex-direction:column;padding:calc(3.4rem + var(--sat)) 4vw calc(1rem + var(--sab));
  opacity:0;pointer-events:none;transition:.3s}
.gridview.open{opacity:1;pointer-events:auto}
.gt{display:flex;gap:.8rem;align-items:center;padding-bottom:.8rem}
.gt input{flex:1;background:#0d0b09;border:1px solid var(--edge);color:var(--skin);border-radius:10px;
  padding:.6rem .9rem;font-size:.9rem;outline:none}
.gt input:focus{border-color:var(--ember)}
.gt .found{font-family:var(--fm);font-size:.66rem;color:var(--ash);white-space:nowrap}
.grid{flex:1;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(172px,1fr));gap:.5rem;align-content:start}
.gi{display:flex;flex-direction:column;gap:.14rem;border:1px solid var(--edge);border-radius:9px;padding:.5rem .65rem;
  text-align:left;transition:.15s;background:rgba(14,11,8,.6)}
.gi:hover{border-color:var(--spoke-glow)}
.gi.cur{border-color:var(--ember);box-shadow:0 0 14px rgba(255,171,64,.18)}
.gi b{font-size:.78rem;font-weight:600}
.gi span{font-family:var(--fm);font-size:.58rem;color:var(--ash)}
.gi.cur span{color:var(--ember)}

/* ── toast / help ── */
.toast{position:fixed;left:50%;bottom:calc(1.2rem + var(--sab));transform:translateX(-50%);z-index:80;
  background:#141009;border:1px solid var(--ember);color:var(--ember);border-radius:10px;
  padding:.55rem 1rem;font-size:.74rem;letter-spacing:.04em;transition:opacity .4s;max-width:92vw;text-align:center}
dialog.help{background:#0b0908;color:var(--skin);border:1px solid var(--edge);border-radius:14px;
  max-width:min(560px,92vw);padding:1.4rem 1.5rem;line-height:1.65}
dialog.help::backdrop{background:rgba(0,0,0,.7)}
dialog.help h2{font-family:var(--fd);font-size:1.05rem;margin-bottom:.7rem;color:var(--ember)}
dialog.help p,dialog.help li{font-size:.82rem;color:var(--ash);margin:.35rem 0}
dialog.help b{color:var(--skin)}
dialog.help kbd{font-family:var(--fm);border:1px solid var(--edge);border-radius:4px;padding:0 .3em;font-size:.72rem}
dialog.help .close-row{text-align:right;margin-top:.8rem}

/* ── панель TASK FILES (все файлы задачи) ── */
.tasksview{position:fixed;inset:0;z-index:62;background:rgba(0,0,0,.92);backdrop-filter:blur(12px);
  display:flex;flex-direction:column;padding:calc(3.4rem + var(--sat)) 4vw calc(.9rem + var(--sab));
  opacity:0;pointer-events:none;transition:.3s}
.tasksview.open{opacity:1;pointer-events:auto}
.tt{display:flex;gap:.7rem;align-items:center;padding-bottom:.7rem;flex-wrap:wrap}
.tt h2{font-family:var(--fd);font-size:.95rem;color:var(--ember);letter-spacing:.06em;white-space:nowrap}
.tt h2 span{color:var(--ash);font-weight:400;font-size:.66rem;letter-spacing:.1em}
.tt input{flex:1;min-width:150px;background:#0d0b09;border:1px solid var(--edge);color:var(--skin);
  border-radius:10px;padding:.55rem .9rem;font-size:.85rem;outline:none}
.tt input:focus{border-color:var(--ember)}
.tmeta{font-family:var(--fm);font-size:.6rem;color:var(--ash);white-space:nowrap}
.tscroll{flex:1;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--edge) transparent;padding-right:.35rem}
.tgroup{margin-bottom:1.05rem}
.tgroup>h3{display:flex;align-items:baseline;gap:.6rem;font-family:var(--fm);font-size:.63rem;
  letter-spacing:.16em;text-transform:uppercase;color:var(--coal2);border-bottom:1px solid var(--edge);
  padding-bottom:.32rem;margin-bottom:.5rem}
.tgroup>h3 .gn{color:var(--mute);letter-spacing:.05em;text-transform:none}
.trow{display:flex;flex-direction:column;gap:.1rem;border:1px solid var(--edge);border-radius:10px;
  background:rgba(14,11,8,.6);padding:.48rem .7rem;margin-bottom:.35rem;transition:border-color .15s}
.trow:hover{border-color:var(--spoke-glow)}
.trow .r1{display:flex;align-items:center;gap:.55rem}
.trow .dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto}
.trow .nm{font-family:var(--fm);font-size:.72rem;color:var(--skin);word-break:break-word;min-width:0}
.trow .sz{margin-left:auto;font-family:var(--fm);font-size:.58rem;color:var(--ash);white-space:nowrap;flex:0 0 auto}
.trow .tstat{font-family:var(--fm);font-size:.52rem;letter-spacing:.14em;text-transform:uppercase;flex:0 0 auto}
.trow .rl{font-size:.66rem;color:var(--mute);padding-left:1.05rem;line-height:1.5}
.trow.live .dot{background:var(--ember);box-shadow:0 0 8px var(--spoke-glow)}
.trow.live .tstat{color:var(--ember)}
.trow.ok .dot{background:var(--dim)}
.trow.ok .tstat{color:var(--ash)}
.trow.soon .dot{background:none;border:1px dashed var(--mute)}
.trow.soon .tstat{color:var(--mute)}
.trow.soon{opacity:.72}
.trow .dlb{font-family:var(--fm);font-size:.62rem;line-height:1;color:var(--ember);border:1px solid var(--edge);
  border-radius:7px;padding:.32rem .58rem;margin-left:.45rem;white-space:nowrap;transition:.15s;flex:0 0 auto}
.trow .dlb:hover,.trow .dlb:focus-visible{border-color:var(--ember);background:rgba(255,171,64,.12);
  box-shadow:0 0 10px rgba(255,171,64,.25)}
