﻿# ============================================================================
#  C65 ТУННЕЛЬ v1.0.0 — клиент узла CELL-65 для Windows
#  Тянет порты HTTP:18080 и SOCKS5:18081 из Codespace на этот комп
#  (127.0.0.1:18080 / 127.0.0.1:18081) и умеет включать/выключить системный прокси.
#  Требуется GitHub CLI (gh) — скрипт сам предложит поставить через winget.
# ============================================================================

param([string]$Mode = '')

$ErrorActionPreference = 'Continue'
$script:Version = '1.0.0'
$script:Repo    = 'rtynbirf/cell65-host'
$script:Gh      = $null

function Write-Ok([string]$m)   { Write-Host "  [OK] $m" -ForegroundColor Green }
function Write-No([string]$m)   { Write-Host "  [!!] $m" -ForegroundColor Red }
function Write-Wait([string]$m) { Write-Host "  [..] $m" -ForegroundColor Cyan }
function Write-Hint([string]$m) { Write-Host "  [--] $m" -ForegroundColor DarkGray }

function Test-Cmd([string]$name) {
    $c = Get-Command $name -ErrorAction SilentlyContinue
    if ($c -and $c.Source -like '*WindowsApps*') { return $null }
    return $c
}

# --- найти или поставить gh --------------------------------------------------
function Ensure-Gh {
    if (Test-Cmd 'gh') { $script:Gh = 'gh'; return $true }
    foreach ($p in @("$env:ProgramFiles\GitHub CLI\gh.exe", "$env:LOCALAPPDATA\Microsoft\WinGet\Links\gh.exe")) {
        if (Test-Path $p) { $script:Gh = $p; Write-Ok ("gh найден: " + $p); return $true }
    }
    Write-Wait 'gh не найден — ставлю GitHub CLI через winget (один раз)'
    if (Test-Cmd 'winget') {
        & winget install --id GitHub.cli --exact --silent --accept-package-agreements --accept-source-agreements
    } else {
        Write-No 'winget недоступен: поставь GitHub CLI руками — https://cli.github.com/ и запусти заново'
        return $false
    }
    foreach ($p in @("$env:ProgramFiles\GitHub CLI\gh.exe", "$env:LOCALAPPDATA\Microsoft\WinGet\Links\gh.exe")) {
        if (Test-Path $p) { $script:Gh = $p; Write-Ok ("gh поставлен: " + $p); return $true }
    }
    Write-Hint 'gh установлен, но PATH ещё не обновился. ЗАКРОЙ окно и открой C65_ТУННЕЛЬ.bat заново.'
    return $false
}

function Test-GhAuth {
    & $script:Gh auth status 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) {
        Write-No 'gh не залогинен. Сейчас откроется вход через браузер (gh auth login).'
        $answer = Read-Host 'Запустить вход? (Y/n)'
        if ($answer -eq '' -or $answer -match '^[YyДд]') {
            & $script:Gh auth login --hostname github.com --web --git-protocol https
        }
        & $script:Gh auth status 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) { Write-No 'логин не прошёл — запусти скрипт заново после gh auth login'; return $false }
    }
    Write-Ok 'gh залогинен'
    return $true
}

# --- найти наш codespace -----------------------------------------------------
function Get-C65Space {
    $raw = & $script:Gh cs list --json name,state,repository 2>$null
    if ($LASTEXITCODE -ne 0 -or -not $raw) { Write-No 'gh cs list не ответил'; return $null }
    $spaces = @($raw | ConvertFrom-Json)
    if ($spaces.Count -eq 0) {
        Write-No ("нет ни одного codespace. Создай: gh cs create -r " + $script:Repo)
        Write-Hint ('или веб: github.com → ' + $script:Repo + ' → Code → Codespaces → Create codespace on main')
        return $null
    }
    foreach ($s in $spaces) {
        if ($s.repository -eq $script:Repo) {
            Write-Ok ("codespace узла: " + $s.name + " [" + $s.state + "]")
            return $s.name
        }
    }
    Write-Wait ('в ' + $script:Repo + ' codespace не найден, беру первый: ' + $spaces[0].name)
    return $spaces[0].name
}

# --- туннель -----------------------------------------------------------------
function Start-Tunnel {
    $name = Get-C65Space
    if (-not $name) { return }
    Write-Wait ("поднимаю туннель к " + $name + " (18080 и 18081) в отдельном окне")
    $cmd = 'gh cs port-forward -c ' + $name + ' -L 18080:18080 -L 18081:18081'
    Start-Process -FilePath 'cmd.exe' -ArgumentList '/k', 'title C65 TUNNEL (не закрывай!)', '&&', $cmd
    Start-Sleep -Seconds 6
    Test-Tunnel
    Write-Host ""
    Write-Host "  ОКНО С ТУННЕЛЕМ ДЕРЖИ ОТКРЫТЫМ — закроешь окно, отвалится прокси." -ForegroundColor Magenta
    Write-Host ("  Порты на этом компе:  HTTP=127.0.0.1:18080   SOCKS5=127.0.0.1:18081") -ForegroundColor Magenta
}

function Test-Tunnel {
    Write-Wait 'самотест через туннель (ждём 204/204)'
    $h = & curl.exe -fsS -m 12 -x http://127.0.0.1:18080 -o NUL -w '%{http_code}' https://www.gstatic.com/generate_204 2>$null
    $s = & curl.exe -fsS -m 12 -x socks5h://127.0.0.1:18081 -o NUL -w '%{http_code}' https://www.gstatic.com/generate_204 2>$null
    if ("$h" -eq '204' -and "$s" -eq '204') { Write-Ok "туннель жив: http=$h socks5=$s"; return $true }
    Write-No "самотест: http=$h socks5=$s (если 000 — туннель ещё поднимается или codespace спит)"
    Write-Hint 'codespace мог уснуть: разбуди веб-вкладкой github.com/codespaces или gh cs start'
    return $false
}

# --- системный прокси ---------------------------------------------------------
function Set-SysProxy([bool]$on) {
    $key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
    if ($on) {
        Set-ItemProperty -Path $key -Name ProxyEnable -Value 1
        Set-ItemProperty -Path $key -Name ProxyServer -Value '127.0.0.1:18080'
        Set-ItemProperty -Path $key -Name ProxyOverride -Value 'localhost;127.*;10.*;172.16.*;192.168.*;<local>'
        Write-Ok 'СИСТЕМНЫЙ ПРОКСИ ВКЛЮЧЁН: 127.0.0.1:18080 (браузер и Win-программы пойдут через узел C65)'
        Write-Hint 'консольным программам отдельно: $env:HTTPS_PROXY="http://127.0.0.1:18080"'
    } else {
        Set-ItemProperty -Path $key -Name ProxyEnable -Value 0
        Write-Ok 'СИСТЕМНЫЙ ПРОКСИ ВЫКЛЮЧЕН (вернулся твой обычный путь)'
    }
}

function Show-Status {
    Write-Host '  --- gh ---' -ForegroundColor Yellow
    & $script:Gh auth status
    Write-Host '  --- codespaces ---' -ForegroundColor Yellow
    & $script:Gh cs list
    Write-Host '  --- порты 18080/18081 на этом компе ---' -ForegroundColor Yellow
    foreach ($p in @(18080, 18081)) {
        $c = Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue
        if ($c) { Write-Ok ("порт " + $p + ": слушается (туннель стоит)") } else { Write-Hint ("порт " + $p + ": свободен (туннеля нет)") }
    }
    $ip = & curl.exe -fsS -m 12 -x http://127.0.0.1:18080 https://api.ipify.org 2>$null
    if ($ip) { Write-Ok ("выход через узел C65, IP: " + $ip) } else { Write-Hint 'через узел не прошло (туннель не поднят?)' }
    Write-Host '  --- системный прокси ---' -ForegroundColor Yellow
    $k = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
    if ($k.ProxyEnable -eq 1) { Write-Ok ("включён: " + $k.ProxyServer) } else { Write-Hint 'выключен' }
}

# --- меню ---------------------------------------------------------------------
function Show-Menu {
    while ($true) {
        Clear-Host
        Write-Host ""
        Write-Host "  ==========================================" -ForegroundColor Cyan
        Write-Host ("   C65 ТУННЕЛЬ v" + $script:Version + "  ·  узел: " + $script:Repo) -ForegroundColor Cyan
        Write-Host "  ==========================================" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "    1)  ТУННЕЛЬ + САМОТЕСТ  (18080/18081 -> 127.0.0.1)" -ForegroundColor White
        Write-Host "    2)  СИСТЕМНЫЙ ПРОКСИ ВКЛ (127.0.0.1:18080)" -ForegroundColor White
        Write-Host "    3)  СИСТЕМНЫЙ ПРОКСИ ВЫКЛ" -ForegroundColor White
        Write-Host ""
        Write-Host "    4)  СТАТУС (gh, codespaces, порты, IP выхода)" -ForegroundColor Gray
        Write-Host "    0)  ВЫХОД" -ForegroundColor Gray
        Write-Host ""
        $choice = Read-Host "  Выбери цифру и жми Enter"
        switch ($choice) {
            '1' { if ((Ensure-Gh) -and (Test-GhAuth)) { Start-Tunnel }; Read-Host "Enter — в меню" }
            '2' { Set-SysProxy $true;  Read-Host "Enter — в меню" }
            '3' { Set-SysProxy $false; Read-Host "Enter — в меню" }
            '4' { if ((Ensure-Gh) -and (Test-GhAuth)) { Show-Status }; Read-Host "Enter — в меню" }
            '0' { return }
            default { }
        }
    }
}

switch ($Mode.ToLower()) {
    'tunnel'    { if ((Ensure-Gh) -and (Test-GhAuth)) { Start-Tunnel } }
    'proxy-on'  { Set-SysProxy $true }
    'proxy-off' { Set-SysProxy $false }
    'status'    { if ((Ensure-Gh) -and (Test-GhAuth)) { Show-Status } }
    ''          { Show-Menu }
    default     { Write-Host ("Не знаю режим: " + $Mode) -ForegroundColor Red }
}

zalp.v:
﻿# ============================================================
# RUVSON :: ZALIT VSE V GITHUB -> repa rtynbirf/cell65-host
# Odin klik: kloniruet repu, kladet v KOREN:
#   - soderzhimoe papki RUVSON_USTANOVSHCHIK (ps1, bat, profili, repo.txt, md)
#   - faily C65 (README.md, codespace-bootstrap.sh, .devcontainer/, windows-client/)
#   - .gitattributes (poryadok strok: .sh = LF, .ps1/.bat = CRLF)
# i delaet push. Pri pervom push otkroetsya okno vhoda GitHub
# (Git Credential Manager -> Sign in with browser) - odin raz, dalee pomnit.
# ============================================================

$ErrorActionPreference = 'Continue'
$RepoUrl = 'https://github.com/rtynbirf/cell65-host.git'
$Branch  = 'main'

function W($t)  { Write-Host $t -ForegroundColor White }
function Ok($t) { Write-Host ('  [OK] ' + $t) -ForegroundColor Green }
function No($t) { Write-Host ('  [!!] ' + $t) -ForegroundColor Red }
function St($t) { Write-Host ('  ..  ' + $t) -ForegroundColor Cyan }

W ''
W '=================================================='
W '  RUVSON :: ZALIT VSE V GITHUB (cell65-host)'
W '=================================================='

# --- 1. naiti ishodnye papki ryadom so skriptom ------------------------------
$kitDir = $PSScriptRoot
if (-not $kitDir) { $kitDir = Split-Path -Parent $MyInvocation.MyCommand.Path }
$parent = Split-Path -Parent $kitDir

St 'ishchu papku USTANOVSHCHIK (tu, gde lezhit ruvson-setup.ps1)...'
$inst = Get-ChildItem -Path $parent -Directory -Recurse -Depth 3 -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like '*УСТАНОВЩИК*' -and (Test-Path (Join-Path $_.FullName 'ruvson-setup.ps1')) } |
        Select-Object -First 1
if (-not $inst) {
    No 'ne nashel papku RUVSON_УСТАНОВЩИК рядом со скриптом.'
    W '  Распакуй АРХИВ ЦЕЛИКОМ в одну папку и запускай ZALITY_V_GITHUB.bat'
    W '  из папки ЗАЛИТЬ_ВСЁ_В_GITHUB внутри архива.'
    exit 1
}
Ok ('установщик: ' + $inst.FullName)

St 'ishchu papku C65 (для_репы_cell65-host)...'
$c65 = Get-ChildItem -Path $parent -Directory -Recurse -Depth 4 -Filter 'для_репы_cell65-host' -ErrorAction SilentlyContinue |
       Select-Object -First 1
if (-not $c65) {
    No 'ne nashel papku для_репы_cell65-host (файлы хоста C65).'
    W '  Без них зальётся только установщик. Продолжаю? Прервано - положи папку рядом и запусти ещё раз.'
    exit 1
}
Ok ('C65: ' + $c65.FullName)

# --- 2. git na meste? ---------------------------------------------------------
$git = Get-Command git.exe -ErrorAction SilentlyContinue
if (-not $git) {
    St 'git не найден - пробую поставить через winget (разовая история)...'
    $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($wg) {
        winget install --id Git.Git -e --silent --accept-package-agreements --accept-source-agreements | Out-Null
        $env:Path = $env:Path + ';' + "$env:LOCALAPPDATA\Programs\Git\cmd" + ';C:\Program Files\Git\cmd'
        $git = Get-Command git.exe -ErrorAction SilentlyContinue
    } else {
        No 'winget не найден.'
    }
}
if (-not $git) {
    No 'git не установлен. Поставь Git for Windows: https://git-scm.com/download/win'
    W '  (галочки по умолчанию подходят) - и запусти меня ещё раз.'
    exit 1
}
Ok ('git: ' + (git --version))

# --- 3. klon repy ---------------------------------------------------------------
$work = Join-Path $parent '_cell65-host'
if ((Test-Path $work) -and -not (Test-Path (Join-Path $work '.git'))) {
    Remove-Item $work -Recurse -Force
}
if (Test-Path (Join-Path $work '.git')) {
    St 'репа уже склонирована - обновляю с GitHub...'
    git -C $work fetch --quiet origin
    git -C $work reset --quiet --hard origin/$Branch 2>$null
    if ($LASTEXITCODE -ne 0) {
        No 'не вышел сброс локальной копии. Удали папку _cell65-host и запусти меня ещё раз.'
        exit 1
    }
} else {
    St ('клонирую ' + $RepoUrl + ' ...')
    git clone $RepoUrl $work
    if ($LASTEXITCODE -ne 0) {
        No 'клон не вышел: либо нет сети, либо не прошёл вход в GitHub.'
        W '  Запусти меня ещё раз - при клоне откроется окно входа GitHub (Sign in with browser).'
        W '  Либо залей файлы руками: https://github.com/rtynbirf/cell65-host/upload/main'
        W '  (пошагово - в КАК_ЗАЛИТЬ_В_РЕПУ.md, способ Б).'
        exit 1
    }
}
if (-not (Test-Path $work)) { No 'пропала папка клона'; exit 1 }
Ok ('рабочая копия: ' + $work)

# репа может быть совсем пустой (без коммитов) - тогда ветку main создаём сами
git -C $work rev-parse --verify HEAD *> $null
if ($LASTEXITCODE -ne 0) {
    St 'репа пустая - создаю ветку main...'
    git -C $work symbolic-ref HEAD refs/heads/$Branch
}

# подпись коммитов (локально в этой репе, глобальные настройки не трогаем)
$un = git -C $work config user.name
if (-not $un) { git -C $work config user.name 'rtynbirf' }
$ue = git -C $work config user.email
if (-not $ue) { git -C $work config user.email 'rtynbirf@users.noreply.github.com' }

# --- 4. .gitattributes: stroki kak nado (.sh LF, .ps1/.bat CRLF) --------------
$ga = @('* text=auto', '*.sh text eol=lf', '*.ps1 text eol=crlf', '*.bat text eol=crlf', '')
Set-Content -Path (Join-Path $work '.gitattributes') -Value $ga -Encoding ASCII

# --- 5. kopiruem faily v koren repy -------------------------------------------
St 'кладу УСТАНОВЩИК в корень репы...'
Copy-Item -Path (Join-Path $inst.FullName '*') -Destination $work -Recurse -Force
if (Test-Path (Join-Path $work 'backup')) { Remove-Item (Join-Path $work 'backup') -Recurse -Force }
if (Test-Path (Join-Path $work 'установщик_журнал.txt')) { Remove-Item (Join-Path $work 'установщик_журнал.txt') -Force }
if (Test-Path (Join-Path $work 'диагностика_отчёт.txt')) { Remove-Item (Join-Path $work 'диагностика_отчёт.txt') -Force }

St 'кладу C65 (хост + туннель)...'
Copy-Item (Join-Path $c65.FullName 'README.md') $work -Force
Copy-Item (Join-Path $c65.FullName 'codespace-bootstrap.sh') $work -Force
New-Item -ItemType Directory -Path (Join-Path $work '.devcontainer') -Force | Out-Null
Copy-Item (Join-Path $c65.FullName '.devcontainer\devcontainer.json') (Join-Path $work '.devcontainer\') -Force
New-Item -ItemType Directory -Path (Join-Path $work 'windows-client') -Force | Out-Null
Copy-Item (Join-Path $c65.FullName 'windows-client\*') (Join-Path $work 'windows-client\') -Recurse -Force
$howto = Join-Path (Split-Path -Parent $c65.FullName) 'КАК_ЮЗАТЬ_C65.md'
if (Test-Path $howto) { Copy-Item $howto $work -Force }

St 'проверяю папку КАРАОКЕ...'
$kar = Get-ChildItem -Path $parent -Directory -Recurse -Depth 3 -ErrorAction SilentlyContinue |
       Where-Object { $_.Name -like '*КАРАОКЕ*' -and (Test-Path (Join-Path $_.FullName 'КАРАОКЕ-ЛАБ-v5.html')) } |
       Select-Object -First 1
if ($kar) {
    New-Item -ItemType Directory -Path (Join-Path $work 'КАРАОКЕ') -Force | Out-Null
    Copy-Item (Join-Path $kar.FullName '*') (Join-Path $work 'КАРАОКЕ\') -Recurse -Force
    Ok 'КАРАОКЕ: лаборатория + СИНГУЛЯР поехали в репу (папка КАРАОКЕ/)'
} else {
    St 'КАРАОКЕ рядом не найдено - зальётся без него (не страшно)'
}

# --- 6. commit + push ------------------------------------------------------------
git -C $work add -A
$dirty = @(git -C $work status --porcelain)
if ($dirty.Count -gt 0) {
    St ('к коммиту: ' + $dirty.Count + ' файлов...')
    git -C $work commit -m 'RUVSON: ustanovshchik + C65 host v2 (bootstrap, devcontainer, windows client)'
    if ($LASTEXITCODE -ne 0) { No 'коммит не вышел'; exit 1 }
    Ok 'коммит готов'
} else {
    St 'изменений нет - в репе уже самое свежее'
}

St 'push в GitHub... (при первом разе окно входа - веди через браузер)'
git -C $work push -u origin $Branch
if ($LASTEXITCODE -ne 0) {
    No 'push не прошёл. Запусти меня ещё раз: окно входа GitHub должно открыться и запомниться.'
    W '  Если окно не появляется - проверь сеть или залей руками (КАК_ЗАЛИТЬ_В_РЕПУ.md, способ Б).'
    exit 1
}

# --- 7. itog ------------------------------------------------------------------------
W ''
Ok 'ZALITO! Проверка: https://github.com/rtynbirf/cell65-host'
W ('  Локальная копия репы: ' + $work)
W '  Последний коммит:'
git -C $work log -1 --oneline | ForEach-Object { W ('    ' + $_) }
W ''
W '  Теперь ПОДТЯНУТЬ_С_GITHUB.bat на любом компе тянет эти файлы сам.'
W '  Памятка: для автоподтяжки репа должна быть ПУБЛИЧНОЙ (см. КАК_ЗАЛИТЬ_В_РЕПУ.md).'
W '=================================================='
exit 0
